import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import LinkButton from 'flarum/common/components/LinkButton';
import huntUrl from '../utils/huntUrl';
import CollectableCanvas from './CollectableCanvas';
/**
 * The finished Collectable, the member's finishing place and the Reward message.
 */
export default class CompletionSummary extends Component {
  view() {
    const hunt = this.attrs.hunt;
    const parts = (hunt.parts() || []).filter(Boolean).sort((a, b) => a.sort() - b.sort());
    const position = hunt.finishingPosition();
    const rewardHtml = hunt.rewardMessageHtml();
    const url = huntUrl(hunt.slug());
    return m("div", {
      className: "CompletionSummary"
    }, m(CollectableCanvas, {
      hunt: hunt,
      parts: parts,
      complete: true
    }), position ? m("p", {
      className: "CompletionSummary-position"
    }, app.translator.trans('fof-scavenger-hunt.forum.completion_modal.position', {
      position
    })) : null, rewardHtml ? m("div", {
      className: "CompletionSummary-reward"
    }, m("h4", null, app.translator.trans('fof-scavenger-hunt.forum.completion_modal.reward')), m("div", {
      className: "CompletionSummary-rewardMessage"
    }, m.trust(rewardHtml))) : null, url ? m(LinkButton, {
      className: "Button",
      icon: "fas fa-trophy",
      href: url
    }, app.translator.trans('fof-scavenger-hunt.forum.completion_modal.view_hunt')) : null);
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/CompletionSummary', CompletionSummary);