import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import CompletionSummary from './CompletionSummary';
export default class CompletionModal extends Modal {
  hunt = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('scavenger-hunts', this.attrs.huntId, {
      include: 'parts'
    }).then(hunt => {
      this.hunt = hunt;
      m.redraw();
    });
  }
  className() {
    return 'CompletionModal Modal--small';
  }
  title() {
    return this.hunt ? app.translator.trans('fof-scavenger-hunt.forum.completion_modal.title', {
      hunt: this.hunt.title()
    }) : app.translator.trans('fof-scavenger-hunt.forum.completion_modal.loading_title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, this.hunt ? m(CompletionSummary, {
      hunt: this.hunt
    }) : m(LoadingIndicator, null));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/CompletionModal', CompletionModal);